import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Brand = () => {
  const [brands, setBrands] = useState([]);
  const [name, setName] = useState('');
  const [image, setImage] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showForm, setShowForm] = useState(false);
  const role = localStorage.getItem("role");

  useEffect(() => {
    fetchBrands();
  }, []);

  const fetchBrands = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/users/allbrands');
      setBrands(response.data);
    } catch (error) {
      console.error("Error fetching brands:", error);
    }
  };

  const handleAddBrands = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append("name", name);
    formData.append("image", image);
    try {

      const token = localStorage.getItem("token");
      await axios.post('http://localhost:5000/api/users/addbrand', formData, {
        headers: { "Content-Type": "multipart/form-data",
          "Authorization": `Bearer ${token}`,
         }
      });
      setName('');
      setImage(null);
      setShowForm(false);
      fetchBrands();
    } catch (error) {
      console.error("Error adding brand:", error);
    }
  };

  return (
    <div style={styles.page}>
      <div style={styles.centeredHeader}>
        <h1 style={styles.mainTitle}>Brands</h1>
        <input
          type="text"
          placeholder="Search brands..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={styles.searchInput}
        />
      </div>
      <div style={styles.grid}>
        {brands
          .filter((cat) => cat.name.toLowerCase().includes(searchTerm.toLowerCase()))
          .map((cat) => (
            <div key={cat._id} style={styles.cardOuter}>
              <div style={styles.cardImageWrap}>
                <img
                  src={`http://localhost:5000/uploads/${cat.image || ''}`}
                  alt={cat.name}
                  style={styles.cardImageNew}
                  onError={e => { e.target.onerror = null; e.target.src = '/default-brand.png'; }}
                />
              </div>
              <div style={styles.cardTitlePill}>{cat.name}</div>
            </div>
          ))}
      </div>
      {role === "admin" && (
        <button style={styles.fab} onClick={() => setShowForm(true)} title="Add Brand">
          <span style={styles.fabPlus}>+</span>
        </button>
      )}
      {showForm && (
        <div style={styles.modalOverlay} onClick={() => setShowForm(false)}>
          <div style={styles.modalBox} onClick={e => e.stopPropagation()}>
            <h2 style={styles.formTitle}>Add Brand</h2>
            <form onSubmit={handleAddBrands} encType="multipart/form-data" style={styles.form}>
              <input
                type="text"
                placeholder="Enter Brand Name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required
                style={styles.input}
              />
              <input
                type="file"
                accept="image/*"
                onChange={(e) => setImage(e.target.files[0])}
                required
                style={styles.input}
              />
              <div style={{ display: 'flex', gap: 12, marginTop: 8 }}>
                <button type="submit" style={styles.button}>Add</button>
                <button type="button" style={styles.cancelBtn} onClick={() => setShowForm(false)}>Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

const styles = {
  page: {
    minHeight: "100vh",
    background: "linear-gradient(135deg, #181c24 0%, #232a36 100%)",
    fontFamily: "'Segoe UI', sans-serif",
    padding: "0 0 60px 0",
